  // url 不是 /media/ 路径的
  const oldUrls = await pool.query\(""SELECT COUNT\(*\) as total FROM media WHERE mime_type LIKE ''image/%'' AND url NOT LIKE ''%/media/%''""\);
  console.log\(''url 不是 /media/ 路径:'', oldUrls.rows[0].total\);

  // 看几条示例
