  samples.rows.forEach\(r => {
    console.log\(''  ID:'', r.id\);
    console.log\(''    filename:'', r.filename\);
    console.log\(''    url:'', r.url\);
    console.log\(''    sizes_thumbnail_url:'', r.sizes_thumbnail_url\);
  }\);

  await pool.end\(\);
}\)\(\);
")

